#include <iostream>
#include <vector>
#include <queue>
#include <utility>
using namespace std;

struct Edge {
  int u, v;
  double weight;
};

bool compareEdges(const Edge& e1, const Edge& e2) {
  return e1.weight < e2.weight;
}

void kruskalMST(vector<Edge>& edges) {
  vector<int> parent(edges.size());
  for (int i = 0; i < parent.size(); i++) {
    parent[i] = i;
  }

  priority_queue<Edge, vector<Edge>, compareEdges> pq;
  for (const auto& edge : edges) {
    pq.push(edge);
  }

  int numEdges = 0;
  while (!pq.empty()) {
    Edge edge = pq.top();
    int u = findParent(parent, edge.u);
    int v = findParent(parent, edge.v);

    if (u != v) {
      parent[u] = v;
      numEdges++;
      cout << "(" << edge.u << ", " << edge.v << ") weight: " << edge.weight << endl;
    }

    pq.pop();
  }
}

int findParent(vector<int>& parent, int node) {
  if (parent[node] != node) {
    return findParent(parent, parent[node]);
  } else {
    return node;
  }
}

int main() {
  vector<Edge> edges = {{0, 1, 2}, {1, 2, 3}, {2, 3, 4}, {3, 4, 5}};
  kruskalMST(edges);
  return 0;
}
```
