package main

import (
    "fmt"
    "sync"
)

type boundedBuffer[T any] struct {
    buffer  []T
    in     chan T
    out    chan T
    mu      sync.Mutex
    full    bool
}

func (bb *boundedBuffer[T]) Produce(item T) {
    bb.mu.Lock()
    defer bb.mu.Unlock()

    if bb.full {
        fmt.Println("Buffer is full, dropping item")
        return
    }

    bb.buffer[len(bb.buffer)] = item // Append to the buffer
    bb.full = len(bb.buffer) == cap(bb.buffer) // Update full status

    if bb.out != nil {
        // Send item to the consumer
        go func() {
            <-bb.out
            bb.consume(item)
        }()
    }
}

func (bb *boundedBuffer[T]) Consume() T {
    bb.mu.Lock()
    defer bb.mu.Unlock()

    if len(bb.buffer) == 0 {
        fmt.Println("Buffer is empty, blocking consumer")
        <-bb.in // Block until an item is available
    }

    item := bb.buffer[0] // Get the first item from the buffer
    bb.buffer = bb.buffer[1:] // Remove the consumed item
    bb.full = false // Update full status

    if bb.in != nil {
        // Send item to the producer
        go func() {
            bb.in <- item
        }()
    }

    return item
}

